// TEMPORARY review-verification repros for PR #2303 — deleted after the run.
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/io.dart';
import 'package:test/test.dart';

Message _msg(int i) => UserMessage.text('m$i');

Future<Session> _seed(
  MemoryExecutionEnv env,
  String id,
  int records,
) async {
  final repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
  final created = await repo.create(
    JsonlSessionCreateOptions(cwd: '/work', id: id),
  );
  for (var i = 0; i < records; i++) {
    await created.appendMessage(_msg(i));
  }
  return created;
}

void main() {
  group('PR2303 review repros', () {
    late MemoryExecutionEnv env;
    setUp(() {
      env = MemoryExecutionEnv(cwd: '/work');
    });
    tearDown(() async {
      await env.dispose();
    });

    test('REPRO A: count-neutral hard-cap rewrite (drop-1 + append-1 in '
        'one poll gap) silently skips the appended record', () async {
      final created = await _seed(env, 'repro-a', 12);
      final path = (await created.getMetadata()).path;

      final source = FileSessionEventSource(
        env: env,
        resolvePath: (id) async => id == 'repro-a' ? path : null,
        pollInterval: Duration.zero,
      );
      final events = <AttachedSessionEvent>[];
      final sub = source.watch('repro-a').listen(events.add);
      await pumpEventQueue(times: 40);
      expect(events, hasLength(1)); // backlog m0..m11
      expect(events.last.appended, hasLength(12));

      // Hard-cap shape with NET-ZERO count: drop the oldest record and
      // append a new one inside the same poll gap (the steady state of
      // _truncateOldestLocked at the 95 MB cap with uniform record sizes).
      final lines = (await env.readTextLines(path)).valueOrNull!;
      await env.writeFile(
        path,
        '${[lines.first, ...lines.sublist(2)].join('\n')}\n',
      ); // drop m0 only
      await created.appendMessage(_msg(12)); // append m12
      await pumpEventQueue(times: 40);

      // total never changed (13 == 13): no branch fires, m12 invisible.
      expect(events, hasLength(1), reason: 'no event at all on a '
          'count-neutral rewrite');

      // The next append proves m12 is skipped FOREVER, not delayed.
      await created.appendMessage(_msg(13));
      await pumpEventQueue(times: 40);
      expect(events, hasLength(2));
      expect(events.last.appended.map((r) => r.text), ['m13'],
          reason: 'm12 silently skipped — not in any event');

      await sub.cancel();
      await source.dispose();
    });

    test('REPRO B: one unreadable poll (resolvePath -> null) resets the '
        'cursor to 0 and the next poll replays the whole file as a '
        'non-reanchored growth event', () async {
      final created = await _seed(env, 'repro-b', 5);
      final path = (await created.getMetadata()).path;

      var resolveFailure = false;
      final source = FileSessionEventSource(
        env: env,
        resolvePath: (id) async {
          if (id != 'repro-b') return null;
          if (resolveFailure) return null; // one unreadable/missing poll
          return path;
        },
        pollInterval: Duration.zero,
      );
      final events = <AttachedSessionEvent>[];
      final sub = source.watch('repro-b').listen(events.add);
      await pumpEventQueue(times: 40);
      expect(events, hasLength(1)); // backlog m0..m4
      expect(events.last.appended, hasLength(5));

      // One poll where the file cannot be resolved/read (rotation rename
      // window, transient IO failure, session list race).
      resolveFailure = true;
      await pumpEventQueue(times: 40);
      resolveFailure = false;
      await pumpEventQueue(times: 40);

      // The unreadable poll fired a shrink: cursor 0, reanchor notice,
      // then the next poll replays EVERYTHING as a plain growth event.
      final replay = events.length > 1
          ? events[1]
          : throw StateError('no event after the unreadable poll');
      expect(replay.reanchored, isFalse,
          reason: 'the full replay arrives as a growth event');
      expect(replay.appended.map((r) => r.text),
          ['m0', 'm1', 'm2', 'm3', 'm4'],
          reason: 'every already-delivered row re-emitted → duplicates');

      await sub.cancel();
      await source.dispose();
    });

    test('REPRO C: baseline torn tail → quarantine heal replays the '
        'surviving records (anchor never set → resume 0)', () async {
      final created = await _seed(env, 'repro-c', 2);
      final path = (await created.getMetadata()).path;

      // Crash residue: a torn tail line exists BEFORE the watcher's
      // first poll (the viewer attached to a crashed session).
      final lines = (await env.readTextLines(path)).valueOrNull!;
      await env.writeFile(path, '${lines.join('\n')}\n{"type":"torn\n');

      final source = FileSessionEventSource(
        env: env,
        resolvePath: (id) async => id == 'repro-c' ? path : null,
        pollInterval: Duration.zero,
      );
      final events = <AttachedSessionEvent>[];
      final sub = source.watch('repro-c').listen(events.add);
      await pumpEventQueue(times: 40);
      expect(events, hasLength(1)); // backlog: m0, m1 (torn renders null)
      expect(events.last.appended, hasLength(2));

      // Quarantine heal: the owner opens the session, the torn line is
      // dropped from the primary (rewritten from surviving records).
      await env.writeFile(path, '${lines.join('\n')}\n');
      await pumpEventQueue(times: 40);

      // Shrink with a NULL anchor → resume 0 → both records re-emitted.
      expect(events.length, greaterThanOrEqualTo(2));
      final after = events[1];
      expect(after.reanchored, isTrue);
      expect(after.appended.map((r) => r.text), ['m0', 'm1'],
          reason: 'surviving rows re-emitted → duplicates in the viewer');

      await sub.cancel();
      await source.dispose();
    });
  });
}

